package com.capstone.invoicebilling.repository;
import com.capstone.invoicebilling.model.Invoice; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.List; import java.util.Optional;
public interface InvoiceRepository extends MongoRepository<Invoice,String>{ List<Invoice> findByUserIdOrderByCreatedAtDesc(String userId); Optional<Invoice> findByIdAndUserId(String id,String userId); void deleteByIdAndUserId(String id,String userId); }